class HarnessedAgent:
    def __init__(self, max_retries: int = 2) -> None:
        self.max_retries = max_retries
        self.command_history: list[str] = []

    def pre_execution_hook(self, command: str) -> None:
        # 第 7-10 行: 确定性正则守卫，阻断破坏性终端命令调用
        for pattern in FORBIDDEN_PATTERNS:  # ['rm -rf', 'sudo', 'chmod 777']
            if re.search(pattern, command):
                raise PermissionError(f"BLOCKED BY PRE-HOOK: '{pattern}' detected.")

    def loop_detector(self, command: str) -> None:
        # 第 13-18 行: 滑动窗口记忆阻断无限循环重试
        self.command_history.append(command)
        if len(self.command_history) >= self.max_retries:
            recent = self.command_history[-self.max_retries:]
            if len(set(recent)) == 1:
                raise RuntimeError(f"LOOP DETECTOR: '{command}' repeated {self.max_retries}x.")

class CoreHarnessStack:
    def validate_tool_permission(self, tool_name: str, target_path: str = None) -> bool:
        # 第 3-6 行: 最小特权工具白名单
        allowed_tools = ["read_file", "write_file", "run_test", "list_dir"]
        if tool_name not in allowed_tools:
            self.log_event("PERMISSION_DENIED", {"tool": tool_name})
            return False

        # 第 9-14 行: 路径沙箱隔离阻断跨目录越界 (../)
        if target_path:
            workspace = Path(self.workspace_root).resolve()
            abs_target = Path(target_path).resolve()
            if not abs_target.is_relative_to(workspace):
                self.log_event("PATH_TRAVERSAL_BLOCKED", {"path": str(abs_target)})
                return False
        return True

    def run_post_edit_hook(self, file_path: str, code_content: str) -> bool:
        # 第 19-21 行: 敏感秘钥扫描器阻断硬编码 API 凭证
        if "sk-proj-" in code_content:
            self.log_event("SECURITY_VIOLATION", {"file": file_path, "issue": "Secret key"})
            return False
        return True

class SpecVerifier:
    def attempt_write(self, target_file: str, code: str) -> tuple[bool, str]:
        relative = self._normalized(target_file)
        dest = (self.workspace / relative).resolve()

        # 第 6-8 行: 严格范围边界 - 仅允许写入 SPEC.md 中声明的文件
        if relative not in self.allowed_files or relative in self.forbidden_files:
            return False, "SCOPE_VIOLATION"  # 阻断 database.py 等越权文件

        # 第 10-13 行: 非目标过滤器阻断未授权的架构蔓延
        lowered = code.lower()
        if "database" in lowered or "connect_db" in lowered or "oauth2" in lowered:
            return False, "NON_GOAL_VIOLATION"  # 阻断未授权的数据库连接

        # 第 16-19 行: 语法校验确保代码在写入落盘前必然可解析编译
        dest.parent.mkdir(parents=True, exist_ok=True)
        dest.write_text(code, encoding="utf-8")
        ast.parse(code, filename=str(dest))
        return True, str(dest)

class ClaudeCodeHookInterceptor:
    def intercept_pre_tool_use(self, tool_name: str, tool_input: dict) -> tuple[bool, str]:
        # 第 3-7 行: 拦截企图绕过安全权限的危险 CLI 参数
        command = tool_input.get("command", "")
        if tool_name == "Bash":
            for flag in ["--dangerously-skip-permissions", "-y", "--force-all"]:
                if flag in command:
                    return False, f"CLI flag '{flag}' prohibited by policy."
        return True, "PreToolUse check passed."

    @classmethod
    def permission_output(cls, decision: str, reason: str) -> dict:
        # 第 12-16 行: 生成标准 Claude Code PreToolUse JSON 响应 Schema
        return {"hookSpecificOutput": {
            "hookEventName": "PreToolUse",
            "permissionDecision": decision,  # 'allow' | 'deny' | 'ask' | 'defer'
            "permissionDecisionReason": reason,
        }}

class GuardrailsEngine:
    def audit_ast_and_secrets(self, file_path: str, code_content: str) -> tuple[bool, list[str]]:
        # 第 21-25 行: 多厂商敏感凭据扫描 + AST 语法解析预检
        ast.parse(code_content, filename=file_path)
        if re.search(r"(sk-proj-[A-Za-z0-9_\-]{20,}|AKIA[0-9A-Z]{16})", code_content):
            return False, ["CRITICAL: Hardcoded API secret key detected!"]
        return True, ["AST syntax valid. Zero secrets."]

class PermissionEscalationGateway:
    def evaluate_request(self, tool_name: str, params: dict, request_id: str) -> dict:
        risk = self.risk_matrix.get(tool_name, "HIGH")

        # 第 5-7 行: LOW 低风险操作 (只读) -> 自动放行
        if risk == "LOW":
            return {"allowed": True, "content": (self.workspace / params["path"]).read_text("utf-8")}

        # 第 9-11 行: MEDIUM 中风险操作 (写入) -> 记录日志并在工作区沙箱执行
        if risk == "MEDIUM":
            (self.workspace / params["path"]).write_text(params["content"], encoding="utf-8")
            return {"allowed": True, "path": str(self.workspace / params["path"])}

        # 第 13-20 行: CRITICAL 极高风险操作 (git_push) -> 严格由 approvals.json 审批凭证准入
        if risk == "CRITICAL":
            approvals = self._approvals()  # 读取 approvals.json
            if request_id not in approvals:
                self._log({"event": "ESCALATION_BLOCKED", "request_id": request_id})
                return {"allowed": False, "reason": "missing_approval"}
            pending = {"request_id": request_id, "approved_by": approvals[request_id]}
            (self.workspace / "pending_push.json").write_text(json.dumps(pending, indent=2), encoding="utf-8")
            return {"allowed": True, "pending_push": str(self.workspace / "pending_push.json")}

class TDAReliabilityPipeline:
    def run_pytest(self, test_path: str) -> tuple[bool, str]:
        # 第 5-8 行: 启动独立 pytest 子进程，隔离捕获真实退出码与终端输出
        cmd = [sys.executable, "-m", "pytest", test_path, "-q", "--tb=short"]
        proc = subprocess.run(cmd, capture_output=True, text=True)
        return (proc.returncode == 0), (proc.stdout + proc.stderr)

    def extract_failure_traceback(self, pytest_output: str) -> str:
        # 第 11-15 行: 提取精准堆栈与异常类型 (ZeroDivisionError)，注入自愈提示词
        lines = pytest_output.splitlines()
        failures = [l for l in lines if "FAILED" in l or "Error" in l]
        return "\n".join(failures[-8:]) if failures else "Unknown failure"

    def append_anti_regression_test(self, test_file: str, new_test_code: str) -> None:
        # 第 19-23 行: 自动追加防回归测试用例，确保历史缺陷永不再现
        path = self.workspace / test_file
        current = path.read_text("utf-8") if path.exists() else ""
        path.write_text(current + "\n\n" + new_test_code, encoding="utf-8")

from mcp.server.fastmcp import FastMCP
mcp = FastMCP("HarnessSecurityExtension")

# 第 4-9 行: MCP 工具注册 (@mcp.tool()) 暴露强类型哈希与文件摘要工具
@mcp.tool()
def compute_sha256(content: str) -> str:
    """计算代码内容的 SHA-256 完整性摘要"""
    import hashlib
    return hashlib.sha256(content.encode('utf-8')).hexdigest()

# 第 12-16 行: MCP 只读资源注册 (@mcp.resource()) 暴露系统级监控指标
@mcp.resource("harness://system-status")
def get_system_status() -> str:
    """返回当前 Harness 治理堆栈的只读运行状态"""
    return json.dumps({"status": "HEALTHY", "active_hooks": 31, "sandbox": "ENABLED"})

# 第 19-25 行: 异步 stdio 客户端解析 JSON-RPC 2.0 请求与响应
async def call_mcp_tool(tool_name: str, arguments: dict) -> dict:
    request = {"jsonrpc": "2.0", "id": 1, "method": f"tools/{tool_name}", "params": arguments}
    response = await stdio_transport.send_receive(request)
    return response.get("result", {})

class FiveStepSOPPipeline:
    def run_sop(self, spec_path: str, proposed_code: str) -> dict:
        # 步骤 1 & 2: 加载 SPEC.md 契约并在隔离沙箱中执行文件修改
        spec = self.load_spec(spec_path)
        if not self.verify_scope(spec, proposed_code):
            return {"status": "FAILED", "stage": "STEP_2_SANDBOX"}

        # 步骤 3: 运行确定性防护栏 (AST 语法分析 + 凭据泄露扫描)
        ast_ok, issues = self.guardrails.audit_ast_and_secrets("app.py", proposed_code)
        if not ast_ok:
            return {"status": "FAILED", "stage": "STEP_3_GUARDRAILS", "issues": issues}

        # 步骤 4 & 5: 隔离运行 Pytest 并生成标准 Unified Diff 补丁归档
        test_passed, test_log = self.run_pytest_verification("tests/")
        diff = self.generate_unified_diff("app.py", proposed_code)
        self.log_event("SOP_COMPLETED", {"diff_size": len(diff), "tests_passed": test_passed})
        return {"status": "COMPLETED", "diff": diff, "tests_passed": test_passed}

class ProductionHarnessAuditor:
    def audit_repository_gates(self, repo_path: str) -> dict:
        # 第 4-8 行: 自动化审计五道生产就绪准入大门 (5-Gate Ready Check)
        gates = {
            "Gate 1 (Memory Files)": self.check_memory_files(repo_path),
            "Gate 2 (PreToolUse Hooks)": self.check_pre_hooks(repo_path),
            "Gate 3 (Pytest Runner)": self.check_pytest_runner(repo_path),
            "Gate 4 (MCP Declarations)": self.check_mcp_config(repo_path),
            "Gate 5 (Subagent Definitions)": self.check_subagents(repo_path),
        }

        # 第 12-16 行: 计算得分，仅当 5 门全过时授予 PRODUCTION_READY 认证徽章
        passed_count = sum(1 for passed in gates.values() if passed)
        status = "PRODUCTION_READY" if passed_count == 5 else "GATES_FAILED"

        # 第 18-21 行: 生成可审计的结构化评分报告
        return {"status": status, "score": f"{passed_count}/5", "gates": gates}
